import styled from '@emotion/styled';
import { theme } from 'theme';
import { composeStyles } from 'utils/emotion';

type ChipVariantProps = {
  $selected?: boolean;
  $rounded?: boolean;
  $isDisabled?: boolean;
};

export const ChipsContainer = styled.div({
  display: 'flex',
  alignItems: 'center',
  width: '100%',
  flexWrap: 'wrap',
  gap: '8px',
  gridColumn: '1 / -1',
});

export const Chip = styled.button<ChipVariantProps>(
  composeStyles<ChipVariantProps>(
    {
      padding: '8px 12px',
      border: '1px solid #D9D9D9',
      borderRadius: '1rem',
      backgroundColor: 'var(--color-bg-surface_primary, #FFF)',
      fontSize: theme.fonts.fontSizes['1'],
      fontWeight: theme.fonts.fontWeights.medium,
      fontFamily: theme.fonts.paragraph,
      cursor: 'pointer',
      transition: 'all 0.2s ease',

      '&:hover': {
        backgroundColor: '#FFF1C2',
        borderColor: '#FFF1C2',
      },
    },
    {
      $selected: {
        true: {
          backgroundColor: '#FFF1C2',
          borderColor: '#FFF1C2',
          fontWeight: theme.fonts.fontWeights.semibold,
        },
      },
      $rounded: {
        true: {
          borderRadius: '512px',
          padding: '6px 10px',
        },
      },
      $isDisabled: {
        true: {
          opacity: 0.5,
          cursor: 'auto',
          pointerEvents: 'none',

          '&:hover': {
            backgroundColor: '#ffffff',
            borderColor: '#D9D9D9',
          },
        },
      },
    },
  ),
);
